var o=`0224-francesinha`;var a=`world-0224`;var s=`PT`;var i=`southern-europe`;var n=4;var r=38;var l={en:`Francesinha`,ua:`Франсезінья`};var u={en:`A traditional Portugal dish made with beef steak, fresh pork sausage, smoked ham, white bread. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Португалія. Основні інгредієнти: яловичий стейк, сира свиняча ковбаса, копчена шинка, білий хліб. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 10 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 10 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:10,i:[[`beef-steak`,280,`g`],[`fresh-pork-sausage`,250,`g`],[`smoked-ham`,120,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:10,i:[[`white-bread`,320,`g`],[`swiss-cheese`,180,`g`]]},{en:`Melt the fat, stir in flour and cook gently for about 8 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 8 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:8,i:[[`unsalted-butter`,35,`g`],[`all-purpose-flour`,35,`g`],[`light-beer`,250,`ml`],[`tomato-paste`,40,`g`],[`whole-cow-milk`,130,`ml`],[`dijon-mustard`,20,`g`]]},{en:`Roast in a preheated 190°C oven for about 10 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 10 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:10,i:[]}];var h={slug:o,id:a,country:`PT`,region:i,servings:4,minutes:38,title:l,text:u,steps:d};export{s as country,h as default,a as id,r as minutes,i as region,n as servings,o as slug,d as steps,u as text,l as title};